// main.ts
import { NestFactory } from '@nestjs/core';
import { SwaggerModule, DocumentBuilder } from '@nestjs/swagger';
import { AppModule } from './app.module';

async function bootstrap() {
  const app = await NestFactory.create(AppModule);

  // Configuration Swagger
  const config = new DocumentBuilder()
    .setTitle('SawaMart API')
    .setDescription('API pour la plateforme e-commerce SawaMart')
    .setVersion('1.0')
    .addTag('auth', 'Authentification et gestion des utilisateurs')
    .addTag('products', 'Gestion des produits')
    .addTag('orders', 'Gestion des commandes')
    .addBearerAuth() // Pour l'authentification JWT
    .build();

  const document = SwaggerModule.createDocument(app, config);
  SwaggerModule.setup('api-docs', app, document); // Documentation disponible sur /api-docs

  await app.listen(3000);
}
bootstrap();
```<br/><br/>- <code>DocumentBuilder</code> : construction de la configuration Swagger<br/>- <code>setTitle</code>, <code>setDescription</code> : informations sur l'API<br/>- <code>addBearerAuth()</code> : ajout du support JWT pour tester les endpoints sécurisés<br/>- <code>setup('api-docs', app, document)</code> : rend la documentation disponible sur <code>/api-docs</code>

